param([Parameter(Mandatory=$true)][string]$Executable,[Parameter(Mandatory=$true)][string]$OutputDirectory,[int]$TextScale=100,[int]$Width=1000,[int]$Height=650,[switch]$ThumbnailOnly,[switch]$FavoriteOnly,[switch]$ViewerBackOnly)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -TypeDefinition 'using System;using System.Runtime.InteropServices;public static class ManageNative{[DllImport("user32.dll")]public static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);[DllImport("user32.dll")]public static extern bool SetWindowPos(IntPtr h,IntPtr a,int x,int y,int w,int z,uint f);}'
$output=[IO.Path]::GetFullPath($OutputDirectory);if(Test-Path -LiteralPath $output){throw 'Fresh output required'};[IO.Directory]::CreateDirectory($output)|Out-Null
$data=Join-Path $output 'isolated-data';$stateFile=Join-Path $data 'window-state.json';$checks=0;$process=$null
function State{for($attempt=0;$attempt -lt 10;$attempt++){try{$stream=[IO.FileStream]::new($stateFile,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete));$reader=[IO.StreamReader]::new($stream);try{$value=$reader.ReadToEnd()|ConvertFrom-Json}finally{$reader.Dispose()};$script:hasState=$true;return $value}catch{Start-Sleep -Milliseconds 10}};if($script:hasState){throw 'Own diagnostic state could not be read'};return $null}

function Await([scriptblock]$test,[string]$name){$end=[DateTime]::UtcNow.AddSeconds(90);do{$matched=$false;try{$matched=&$test}catch{$transient=$false;$cause=$_.Exception;for($depth=0;$depth -lt 8 -and $cause;$depth++){if($cause.GetType().FullName -eq 'System.Windows.Automation.ElementNotAvailableException'){$transient=$true;break};$cause=$cause.InnerException};if(-not $transient){throw}};if($matched){return};if($process.HasExited){throw ('EXIT '+$name)};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow -lt $end);throw ('TIMEOUT '+$name)}

function Checkpoint([string]$name){Await {$s=State;return -not $s.workspace.management.loading -and -not $s.workspace.management.writing -and $s.revision -eq $s.captureRevision} ('capture '+$name);$s=State;@{name=$name;capture=$s.captures[-1];revision=$s.revision}|ConvertTo-Json -Compress|Add-Content -LiteralPath (Join-Path $output 'checkpoints.jsonl')}
function Check([bool]$value,[string]$name){if(-not $value){throw ('MANAGEMENT_FAIL '+$name)};$script:checks++}
function SelectFirstModel{
 Await {$list=Find 'ManageList';if(-not $list -or -not $list.Current.IsEnabled){return $false};$script:firstModel=$list.FindFirst([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::ControlTypeProperty,[Windows.Automation.ControlType]::ListItem));return $null -ne $script:firstModel} 'first model card realized'
 $script:firstModel.GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Select()
 Await {$null -ne (Find 'ManageSelectedModel')} 'selected model inspector'
}
try{
 $start=[Diagnostics.ProcessStartInfo]::new([IO.Path]::GetFullPath($Executable));$start.UseShellExecute=$false;$start.WindowStyle='Hidden';$start.Arguments='--data-dir "'+$data+'" --diagnostics --capture --text-scale '+$TextScale
 $process=[Diagnostics.Process]::Start($start);Await {(State).ready -and (State).revision -eq (State).captureRevision} 'ready';$root=[Windows.Automation.AutomationElement]::FromHandle([IntPtr][long](State).hwnd);[ManageNative]::SetWindowPos([IntPtr][long](State).hwnd,[IntPtr]::Zero,0,0,$Width,$Height,0x14)|Out-Null
 function Find([string]$id){return $root.FindFirst([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::AutomationIdProperty,$id))}
 function Reach([string]$id){Await {$e=Find $id;if(-not $e -or -not $e.Current.IsEnabled){return $false};$rect=$e.Current.BoundingRectangle;$minimum=if($id.StartsWith("Nav") -and $id -ne "NavSettings"){48}else{0};$parent=[Windows.Automation.TreeWalker]::ControlViewWalker.GetParent($e);$ancestors=@();for($level=0;$level -lt 16 -and $parent;$level++){if($parent.Current.ProcessId -ne $process.Id){break};$sp=$null;if($parent.TryGetCurrentPattern([Windows.Automation.ScrollPattern]::Pattern,[ref]$sp)){$ancestors+=,@($parent,$sp)};if($parent.Current.NativeWindowHandle -eq $root.Current.NativeWindowHandle -and $parent.Current.NativeWindowHandle -ne 0){break};$parent=[Windows.Automation.TreeWalker]::ControlViewWalker.GetParent($parent)}
  for($ancestorIndex=$ancestors.Count-1;$ancestorIndex -ge 0;$ancestorIndex--){$pair=$ancestors[$ancestorIndex];$scroll=$pair[0];$pattern=$pair[1];$viewport=$scroll.Current.BoundingRectangle;$ownBounds=$root.Current.BoundingRectangle;$viewport.Intersect($ownBounds);if($rect.Height -gt 0 -and $rect.Top -ge $viewport.Top-1 -and $rect.Bottom -le $viewport.Bottom+1 -and $rect.Height -ge [Math]::Max(1,$minimum-1)){continue};if($pattern.Current.VerticallyScrollable){$direction=if($rect.Height -gt 0 -and ($rect.Top -lt $viewport.Top -or ($rect.Height -lt $minimum-1 -and $rect.Top -le $viewport.Top+1))){[Windows.Automation.ScrollAmount]::SmallDecrement}else{[Windows.Automation.ScrollAmount]::SmallIncrement};if($e.Current.IsOffscreen -and $pattern.Current.VerticalScrollPercent -ge 99){$pattern.SetScrollPercent(-1,0)}else{$pattern.Scroll([Windows.Automation.ScrollAmount]::NoAmount,$direction)}};return $false};$bounds=$root.Current.BoundingRectangle;$script:reachedElement=$e;return -not $e.Current.IsOffscreen -and $rect.Height -ge [Math]::Max(1,$minimum-1) -and $rect.Top -ge $bounds.Top -and $rect.Bottom -le $bounds.Bottom} ('fully reachable '+$id)}

 function Click([string]$id){Reach $id;$script:reachedElement.GetCurrentPattern([Windows.Automation.InvokePattern]::Pattern).Invoke();$script:checks++;if($id.StartsWith('Nav')){$page=$id.Substring(3);Await {$s=State;return $s.workspace.page -eq $page -and -not $s.workspace.management.loading -and $s.revision -eq $s.captureRevision} ('settled '+$page)}}
 function SetText([string]$id,[string]$value){Reach $id;$e=Find $id;$e.GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).SetValue($value)}
 Click 'GalleryOpen';Await {(State).workspace.gallery.itemCount -eq 120 -and -not (State).workspace.gallery.loading} 'gallery'
 if($ThumbnailOnly){Click 'NavSettings';Await {$e=Find 'ManagePreferenceThumbnail';return $e -and $e.Current.IsEnabled -and -not (State).workspace.management.loading} 'thumbnail preference';Reach 'ManagePreferenceThumbnail';(Find 'ManagePreferenceThumbnail').GetCurrentPattern([Windows.Automation.RangeValuePattern]::Pattern).SetValue(1200);Click 'ManageSavePreferences';Await {(State).workspace.gallery.preferredThumbnailSize -eq 1200 -and -not (State).workspace.management.writing} 'applied';Click 'NavGallery';Click 'GalleryRefresh';Await {(State).workspace.gallery.thumbnailActive -eq 0 -and (State).workspace.gallery.thumbnailQueue -eq 0 -and ((State).workspace.gallery.thumbnailCompleted -gt 0 -or (State).workspace.gallery.thumbnailFailed -gt 0)} 'decode finished';Check ((State).workspace.gallery.thumbnailCompleted -gt 0 -and (State).workspace.gallery.thumbnailFailed -eq 0) '1200 thumbnails actually decode';Click 'ClosePreview';$process.WaitForExit(30000)|Out-Null;Write-Output ('THUMBNAIL_PASSED '+$checks);return}
 if($ViewerBackOnly){(Find 'GalleryImage1').GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Select();(Find ('GalleryImage'+(State).workspace.gallery.currentId)).SetFocus();[ManageNative]::PostMessage([IntPtr][long](State).hwnd,0x100,[IntPtr]13,[IntPtr]0)|Out-Null;[ManageNative]::PostMessage([IntPtr][long](State).hwnd,0x101,[IntPtr]13,[IntPtr]0)|Out-Null;Await {(State).workspace.viewer.displayedId -eq 1} 'viewer current';Click 'ViewerBack';Await {-not (State).workspace.viewer.open -and (State).revision -eq (State).captureRevision} 'viewer back';$capture=Join-Path $data @((State).captures)[-1];$colors=(& (Join-Path $PSScriptRoot '../../../.venv-build/Scripts/python.exe') -c 'from PIL import Image;import sys;im=Image.open(sys.argv[1]);print(len(im.crop((0,0,180,im.height)).getcolors(180*im.height)))' $capture);Check ([int]$colors -gt 10) 'own captured navigation is visibly restored after viewer';Click 'ClosePreview';$process.WaitForExit(30000)|Out-Null;return}
 if($FavoriteOnly){(Find 'GalleryImage1').GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Select();Await {(State).workspace.gallery.currentId -eq 1} 'favorite target';Click 'GalleryHeart1';Await {$s=State;return $s.workspace.gallery.currentFavorite -and -not $s.workspace.gallery.annotationWriting -and -not $s.workspace.gallery.loading -and $s.revision -eq $s.captureRevision} 'favorite settled';Check ((State).workspace.gallery.currentId -eq 1 -and (Find 'GalleryHeart1').Current.Name -eq '取消收藏') 'favorite preserves current image';Click 'ClosePreview';$process.WaitForExit(30000)|Out-Null;return}
 function ContinueDialog{Await {$null -ne (Find 'PrimaryButton')} 'confirmation';(Find 'PrimaryButton').GetCurrentPattern([Windows.Automation.InvokePattern]::Pattern).Invoke()}
 function Gate([string]$name){
  $script:gateRelease=Join-Path $output ($name+'-release');$ready=Join-Path $output ($name+'-ready');[IO.File]::WriteAllText((Join-Path $output 'synthetic-model-test.marker'),'synthetic only')
  $db=@(Get-ChildItem -LiteralPath $data -Recurse -File -Filter 'library.sqlite3');Check ($db.Count -eq 1) 'one owned synthetic catalog'
  $startGate=[Diagnostics.ProcessStartInfo]::new((Join-Path $PSScriptRoot '../../../.venv-build/Scripts/python.exe'));$startGate.UseShellExecute=$false;$startGate.CreateNoWindow=$true;$startGate.WindowStyle='Hidden'
  foreach($arg in @((Join-Path $PSScriptRoot 'synthetic_sqlite_gate.py'),$db[0].FullName,$ready,$script:gateRelease)){$startGate.ArgumentList.Add($arg)}
  $script:gateProcess=[Diagnostics.Process]::Start($startGate);Await {Test-Path -LiteralPath $ready} 'synthetic write gate';Check ((State).workspace.management.activeJobs -gt 0) 'model task really active under gate'
 }
 function ReleaseGate{if($script:gateRelease){[IO.File]::WriteAllText($script:gateRelease,'release')};if($script:gateProcess){Check ($script:gateProcess.WaitForExit(10000) -and $script:gateProcess.ExitCode -eq 0) 'write gate safely released'}}
 function SelectFirstRoot{
  Reach 'ManageModelRoots';(Find 'ManageModelRoots').GetCurrentPattern([Windows.Automation.ExpandCollapsePattern]::Pattern).Expand()
  Await {$script:firstRoot=$null;foreach($window in [Windows.Automation.AutomationElement]::RootElement.FindAll([Windows.Automation.TreeScope]::Children,[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::ProcessIdProperty,$process.Id))){$entry=$window.FindFirst([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::NameProperty,'synthetic-models · 1 个'));if($entry){$pattern=$null;if($entry.TryGetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern,[ref]$pattern)){$script:firstRoot=$pattern;return $true}}};return $false} 'first folder option'
  try{$script:firstRoot.Select()}catch{if((State).workspace.management.modelRootId -ne 1){throw}};Await {(State).workspace.management.modelRootId -eq 1 -and (State).workspace.management.modelCount -eq 1 -and -not (State).workspace.management.loading} 'first folder selected'
 }
 Click 'NavModels';$models=Join-Path $output 'synthetic-models';[IO.Directory]::CreateDirectory($models)|Out-Null;$bytes=[Text.Encoding]::UTF8.GetBytes('inert synthetic weight never deserialize');[IO.File]::WriteAllBytes((Join-Path $models '合成模型 SDXL.safetensors'),$bytes)
 Click 'ManageShowModelPath';SetText 'ManageModelPath' $models;Click 'ManageAddModelRoot';Await {(State).workspace.management.rootCount -eq 1 -and -not (State).workspace.management.loading} 'first directory';Await {(State).workspace.management.modelCount -eq 1 -and -not (State).workspace.management.loading} 'first model'
 $large=Join-Path $output 'synthetic-many';[IO.Directory]::CreateDirectory($large)|Out-Null;for($i=0;$i -lt 6000;$i++){[IO.File]::WriteAllBytes((Join-Path $large ('模型{0:D4}.bin' -f $i)),$bytes)}
 Click 'ManageShowModelPath';SetText 'ManageModelPath' $large;Click 'ManageAddModelRoot';Await {(State).workspace.management.rootCount -eq 2 -and -not (State).workspace.management.loading} 'large directory'
 Await {(State).workspace.management.activeJobs -gt 0 -and -not (State).workspace.management.writing} 'scan started';Gate 'draft'
 Click 'ManageRegistry';SetText 'ManageRegistryMatch' 'synthetic-unsaved-rule';SetText 'ManageRegistryNote' 'must survive task completion';ReleaseGate
 Await {(State).workspace.management.activeJobs -eq 0} 'scan finishes while editing'
 Check ((State).workspace.management.subpage -eq 'registry' -and (Find 'ManageRegistryMatch').GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).Current.Value -eq 'synthetic-unsaved-rule') 'task completion preserves unsaved rule'
 Checkpoint 'draft-retained'
 Click 'ManageRegistryReturn';Await {(State).workspace.management.modelTotal -eq 6000 -and -not (State).workspace.management.loading} 'full inventory after editor return'
 Click 'ManageModelNext';Await {(State).workspace.management.modelPage -eq 2 -and -not (State).workspace.management.loading} 'second model page'
 SelectFirstModel;Click 'ManageReclassify';ContinueDialog;Await {(State).workspace.management.activeJobs -eq 0 -and -not (State).workspace.management.loading -and -not (State).workspace.management.writing -and (State).workspace.management.modelPage -eq 1} 'reclassification refresh resets expired cursor'
 Check ((State).workspace.management.modelTotal -eq 6000 -and (State).workspace.management.modelRootId -eq 2) 'task retains directory filter'
 # Freeze the real scan writer after its first commits so a valid page-two cursor
 # can be captured, then prove completion invalidates it even inside an editor.
 Click 'ManageRefresh';Await {(State).workspace.management.activeJobs -gt 0 -and -not (State).workspace.management.writing} 'delayed scan started';Gate 'cursor'
 Click 'ManageRefresh';Await {-not (State).workspace.management.loading} 'frozen scan refresh';Click 'ManageModelNext';Await {(State).workspace.management.modelPage -eq 2 -and -not (State).workspace.management.loading} 'valid second page while scan gated'
 Click 'ManageRegistry';SetText 'ManageRegistryMatch' 'synthetic-second-draft';ReleaseGate;Await {(State).workspace.management.activeJobs -eq 0} 'gated scan completes in editor'
 Check ((State).workspace.management.modelPage -eq 1 -and (Find 'ManageRegistryMatch').GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).Current.Value -eq 'synthetic-second-draft') 'completion invalidates cursor while preserving editor'
 Click 'ManageRegistryReturn';Await {(State).workspace.management.modelTotal -eq 6000 -and (State).workspace.management.modelCount -eq 60 -and -not (State).workspace.management.loading} 'editor returns to current inventory'
 Click 'ManageRefresh';Await {(State).workspace.management.activeJobs -gt 0 -and -not (State).workspace.management.writing} 'rescan started';Gate 'viewer'
 SelectFirstRoot;SelectFirstModel;Click 'ManageModelDetails';Click 'ManageCandidateImages';Await {(State).workspace.management.linkedTotal -eq 66} 'candidate scope'
 Click 'ManageLinkedImage1';Await {(State).workspace.viewer.open -and (State).workspace.viewer.displayedId -eq 1} 'native viewer during task';ReleaseGate
 Click 'ViewerBack';Await {-not (State).workspace.viewer.open -and (State).workspace.management.activeJobs -eq 0} 'task tracking resumes after viewer'
 Check ((State).workspace.management.associationMode -eq 'candidate' -and (State).workspace.management.linkedTotal -eq 66) 'viewer return preserves candidate view'
 Checkpoint 'viewer-task-complete'
 Check ([BitConverter]::ToString([IO.File]::ReadAllBytes((Join-Path $models '合成模型 SDXL.safetensors'))) -eq [BitConverter]::ToString($bytes)) 'first synthetic weight unchanged'
 for($i=0;$i -lt 6000;$i++){if([BitConverter]::ToString([IO.File]::ReadAllBytes((Join-Path $large ('模型{0:D4}.bin' -f $i)))) -ne [BitConverter]::ToString($bytes)){throw 'Synthetic weight changed'}};Check $true 'all 6000 synthetic weights unchanged'
 Click 'ClosePreview';Check ($process.WaitForExit(30000) -and $process.ExitCode -eq 0) 'safe close'
 @{result='passed';count=$checks;syntheticModels=6001;state=(State);syntheticOnly=$true}|ConvertTo-Json -Depth 14|Set-Content -LiteralPath (Join-Path $output 'model-task-window-report.json');Write-Output ('MODEL_TASK_WINDOW_PASSED '+$checks)
}catch{(State)|ConvertTo-Json -Depth 14|Set-Content -LiteralPath (Join-Path $output 'failure-state.json');($_|Format-List * -Force|Out-String)|Set-Content -LiteralPath (Join-Path $output 'exception.txt');throw}finally{if($script:gateRelease){[IO.File]::WriteAllText($script:gateRelease,'release')};if($script:gateProcess){$script:gateProcess.WaitForExit(30000)|Out-Null};if($process -and -not $process.HasExited){$process.CloseMainWindow()|Out-Null;$process.WaitForExit(30000)|Out-Null}}
